namespace Kaff.Api.Features.DailyLogs.RecordQuantity;

/// <summary>An executed quantity: a period delta against one BOQ line, never a running total (spec.md section 8).</summary>
/// <param name="EntryId">Generated by the device, so a retried sync is recognised and not counted twice.</param>
/// <param name="BoqLineId">A line of this project's frozen BOQ.</param>
/// <param name="Quantity">What was done in this period. Positive.</param>
/// <param name="OccurredAt">When it happened on site, with the device's offset. Decides which day it belongs to.</param>
public sealed record Request(Guid? EntryId, Guid? BoqLineId, decimal Quantity, DateTimeOffset? OccurredAt);
